from scipy.optimize import least_squares
forms={
 'tv_pow': lambda p: t**p[1]*v**p[2],
 'tv_expv': lambda p: t**p[1]*np.exp(-p[2]*v),
 'xt_expt': lambda p: x**p[1]*np.exp(-p[2]*t),
 'xt_cos': lambda p: x**p[1]*np.cos(p[2]*t),
 'xv_exp': lambda p: x**p[1]*np.exp(-p[2]*v),
 'xv_pow': lambda p: x**p[1]*v**p[2],
 'xt_pow': lambda p: x**p[1]*t**p[2],
}
results={}
for name,f in forms.items():
    best=None
    rng=np.random.default_rng(1)
    for i in range(40):
        p0=[rng.uniform(0.005,1),rng.uniform(-2,2),rng.uniform(-1,1.5)]
        def rr(p):
            A=np.column_stack([v**1.5,np.exp(-p[0]*t**2),f(p)])
            c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
            return dv_dt-A@c
        try:
            r=least_squares(rr,p0)
            val=np.mean(r.fun**2)/np.var(dv_dt)
            if best is None or val<best[0]: best=(val,r.x)
        except Exception: pass
    results[name]=best
